  "sql": "SELECT\n  customers__regions.name AS \"orders.customers.regions.name\",\n  DATE_TRUNC('MONTH', orders.order_date) AS \"orders.order_date\",\n  CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.rev\"\nFROM orders AS orders\nLEFT JOIN customers AS customers\n  ON orders.customer_id = customers.id\nLEFT JOIN regions AS customers__regions\n  ON customers.region_id = customers__regions.id\nWHERE\n  (\n    orders.order_date >= CAST('2025-01-01' AS DATE)\n    AND orders.order_date < CAST('2025-04-01' AS DATE)\n  )\nGROUP BY\n  customers__regions.name,\n  DATE_TRUNC('MONTH', orders.order_date)\nORDER BY\n  \"orders.order_date\" ASC,\n  \"orders.customers.regions.name\" ASC\nLIMIT 101"
